// === Zentrale Konfiguration – hier pflegen ===

// Rollierendes Fenster: die letzten TAGE Tage bis jetzt.
const TAGE = 90;
const jetzt = new Date();
const von = new Date(jetzt.getTime() - TAGE * 24 * 60 * 60 * 1000);

const CONFIG = {
  shop: 'vdzvc0-nd',
  apiVersion: '2024-10',

  tage: TAGE,
  // Wird bei jedem Lauf neu berechnet, daher kein fixes Datum im Code.
  createdAtMin: von.toISOString(),
  // null = "bis jetzt". Fixes Ende z.B.: '2026-09-01T21:59:59Z'
  createdAtMax: null,

  // Produktunabhängig: keine Pflicht-SKU. Zum Einschränken hier eine SKU
  // eintragen, dann greift der Flow nur auf Bestellungen mit dieser Position.
  pflichtSku: null,

  // Optionaler Länderfilter, z.B. ['DE'] oder ['DE','AT']. null = alle.
  nurLaender: null,

  // Einzelne Bestellungen ausschließen (orderId als Zahl)
  ausnahmen: [],

  // === Stufe 2: Refund-Kette ===

  // true = es wird NICHTS erstattet, der Flow protokolliert nur, was er täte.
  // Für den ersten scharfen Lauf einmal auf true stellen und den Report lesen.
  trockenlauf: true,

  // Gestaffelte Sicherungen gegen einen systematischen Fehler. Dieser Flow
  // läuft täglich und produktunabhängig – er hat keine Pflicht-SKU als
  // Sicherheitsgurt, also muss die Betragsseite ihn ersetzen.
  mindestBetrag: 0.01,        // darunter: kein Refund (Centbeträge)
  maxBetrag: 10.00,           // pro Bestellung – darüber: manuell prüfen
  maxSummeProLauf: 150.00,    // Summe aller Refunds eines Laufs
  maxKandidatenProLauf: 50,   // darüber: Notbremse, gar kein Refund im Lauf

  // Tag nach erfolgreichem Refund – macht die Läufe im Admin nachvollziehbar
  tag: `n8n-api-${$workflow.id}`,

  notifyCustomer: false,
  note: 'Automatische Rückerstattung offener Saldo'
};

const staticData = $getWorkflowStaticData('global');
staticData.config = CONFIG;
staticData.kandidaten = [];
staticData.skipped = [];
staticData.ergebnisse = {};
staticData.refundSumme = 0;
staticData.stats = { seiten: 0, geprueft: 0, ohneOffenenSaldo: 0 };

return [{ json: { config: CONFIG } }];

const config = $('Config').first().json.config;
const shop = config.shop;

let initUrl = `https://${shop}.myshopify.com/admin/api/${config.apiVersion}/orders.json`
  + `?limit=250`
  + `&status=any`
  + `&order=${encodeURIComponent('created_at asc')}`
  + `&created_at_min=${encodeURIComponent(config.createdAtMin)}`
  + `&fields=id,name,created_at,currency,presentment_currency,financial_status,`
  + `total_price,current_total_price,total_outstanding,shipping_address,line_items,`
  + `refunds,tags`;

if (config.createdAtMax) {
  initUrl += `&created_at_max=${encodeURIComponent(config.createdAtMax)}`;
}

// Zweiter Reset: der Flow laeuft taeglich, staticData ueberlebt Executions.
const staticData = $getWorkflowStaticData('global');
staticData.kandidaten = [];
staticData.skipped = [];
staticData.ergebnisse = {};
staticData.refundSumme = 0;
staticData.stats = { seiten: 0, geprueft: 0, ohneOffenenSaldo: 0 };

return [{
  json: {
    nextUrl: initUrl,
    hasNext: true,
    accessToken: $('Token holen').first().json.access_token
  }
}];

const response = $input.first().json;
const orders = response.body?.orders || response.orders || [];
const headers = response.headers || {};

const config = $('Config').first().json.config;
const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.kandidaten)) staticData.kandidaten = [];
if (!Array.isArray(staticData.skipped)) staticData.skipped = [];
if (!staticData.stats) staticData.stats = { seiten: 0, geprueft: 0, ohneOffenenSaldo: 0 };

staticData.stats.seiten++;
let gesamt = 0;

for (const order of orders) {
  gesamt++;
  staticData.stats.geprueft++;

  // REST liefert total_outstanding als String. Negativ = wir schulden dem Kunden.
  // null/'' waeren bei Number() eine 0 und wuerden lautlos rausfallen -> vorher abfangen.
  const roh = order.total_outstanding;
  const outstanding = (roh === null || roh === undefined || roh === '') ? NaN : Number(roh);

  if (!Number.isFinite(outstanding)) {
    staticData.skipped.push({
      orderId: order.id, orderName: order.name,
      grund: 'total_outstanding fehlt oder ist unlesbar: ' + roh
    });
    continue;
  }

  // Kein Guthaben zugunsten des Kunden -> still verwerfen, sonst wird der
  // Report so lang wie die Bestellliste.
  if (outstanding >= 0) {
    staticData.stats.ohneOffenenSaldo++;
    continue;
  }

  const aktivePositionen = (order.line_items || [])
    .filter(li => Number(li.current_quantity) > 0);

  // Bereits erstattete Summe aus den Refund-Transaktionen der Bestellung.
  const bereitsErstattet = (order.refunds || []).reduce((s, r) =>
    s + (r.transactions || []).reduce((t, tx) => t + Number(tx.amount || 0), 0), 0);

  const offenerBetrag = Math.abs(outstanding);

  // Vorab-Einstufung fuer Stufe 2 - hier wird noch nichts erstattet.
  let einstufung = 'AUTO_REFUND_FAEHIG';
  if (offenerBetrag < config.mindestBetrag) einstufung = 'UNTER_MINDESTBETRAG';
  else if (offenerBetrag > config.maxBetrag) einstufung = 'UEBER_MAXBETRAG_MANUELL';

  const datensatz = {
    orderId: order.id,
    orderName: order.name,
    createdAt: order.created_at,
    currency: order.presentment_currency || order.currency,
    land: order.shipping_address?.country_code || null,
    financialStatus: order.financial_status,
    totalPrice: order.total_price,
    totalOutstandingRest: order.total_outstanding,
    offenerBetrag: offenerBetrag.toFixed(2),
    bereitsErstattet: bereitsErstattet.toFixed(2),
    anzahlRefunds: (order.refunds || []).length,
    einstufung,
    orderTags: order.tags || '',
    aktivePositionen: aktivePositionen.length,
    aktiveSkus: aktivePositionen.map(li => String(li.sku || '').trim())
  };

  if (Array.isArray(config.ausnahmen) && config.ausnahmen.includes(order.id)) {
    staticData.skipped.push({ ...datensatz, grund: 'Bestellung steht in Config.ausnahmen' });
    continue;
  }

  // Produktunabhaengig: greift nur, wenn in der Config eine SKU gesetzt ist.
  if (config.pflichtSku && !datensatz.aktiveSkus.includes(String(config.pflichtSku).trim())) {
    staticData.skipped.push({ ...datensatz, grund: 'Pflicht-SKU ' + config.pflichtSku + ' nicht in der Bestellung' });
    continue;
  }

  if (Array.isArray(config.nurLaender) && !config.nurLaender.includes(datensatz.land)) {
    staticData.skipped.push({ ...datensatz, grund: 'Land ' + datensatz.land + ' nicht in Config.nurLaender' });
    continue;
  }

  staticData.kandidaten.push(datensatz);
}

// Cursor-Pagination über Link-Header (rel="next").
// Filterparameter gehören NUR in die erste URL, danach nur page_info + limit.
const linkHeader = String(headers.link || headers.Link || '');
let nextUrl = null;
const nextPart = linkHeader.split(',').find(p => p.includes('rel="next"'));
if (nextPart) {
  const m = nextPart.match(/<([^>]+)>/);
  if (m) nextUrl = m[1];
}

return [{
  json: {
    nextUrl: nextUrl,
    hasNext: !!nextUrl,
    seiteBestellungen: gesamt,
    bestellungenGeprueft: staticData.stats.geprueft,
    kandidatenGesamt: staticData.kandidaten.length,
    uebersprungenGesamt: staticData.skipped.length
  }
}];

const tokenItem = $input.first().json;
const urlItem = $input.last().json;

return [{
  json: {
    accessToken: tokenItem.access_token,
    nextUrl: urlItem.nextUrl,
    hasNext: urlItem.hasNext
  }
}];

const config = $('Config').first().json.config;
const staticData = $getWorkflowStaticData('global');
const kandidaten = staticData.kandidaten || [];

// Notbremse: finden sich auf einmal auffaellig viele Kandidaten, ist mit hoher
// Wahrscheinlichkeit etwas systematisch kaputt (Filter, Datenlage, API).
// Dann wird in diesem Lauf GAR NICHTS erstattet - auch nicht die ersten paar.
const notbremse = kandidaten.length > config.maxKandidatenProLauf;
staticData.notbremse = notbremse;

// Ein Item pro Kandidat. Daran haengt die Refund-Kette.
return kandidaten.map(k => ({
  json: {
    ...k,
    notbremse,
    orderGid: `gid://shopify/Order/${k.orderId}`,
    adminUrl: `https://admin.shopify.com/store/${config.shop}/orders/${k.orderId}`
  }
}));

const config = $('Config').first().json.config;
const staticData = $getWorkflowStaticData('global');
const kandidaten = staticData.kandidaten || [];
const skipped = staticData.skipped || [];
const ergebnisse = staticData.ergebnisse || {};
const stats = staticData.stats || { seiten: 0, geprueft: 0, ohneOffenenSaldo: 0 };

// Kandidat + Refund-Ergebnis zu einer Zeile zusammenfuehren. Die Zeilenart
// bleibt KANDIDAT, damit der Mail-Node unveraendert weiterlaeuft.
const zeilen = kandidaten.map(k => {
  const e = ergebnisse[k.orderId] || {};
  return {
    ...k,
    refundStatus: e.status || 'NICHT_VERARBEITET',
    refundBetrag: e.refundBetrag || '0.00',
    refundId: e.refundId || null,
    tagGesetzt: e.tagGesetzt === true,
    manuellPruefen: e.manuellPruefen === true || !ergebnisse[k.orderId],
    grund: e.grund || (ergebnisse[k.orderId] ? null : 'Kein Ergebnis – Loop abgebrochen?')
  };
});

const summe = (liste, feld) => liste
  .reduce((s, r) => s + Number(r[feld] || 0), 0)
  .toFixed(2);

const nach = (s) => zeilen.filter(z => z.refundStatus === s);
const erstattet = zeilen.filter(z => z.refundStatus === 'OK');
const pending = nach('PENDING');
const trocken = nach('TROCKENLAUF');
const pruefen = zeilen.filter(z => z.manuellPruefen);

const zusammenfassung = {
  zeile: 'ZUSAMMENFASSUNG',
  lauf: new Date().toISOString(),
  modus: config.trockenlauf ? 'TROCKENLAUF – es wurde nichts erstattet' : 'SCHARF',
  notbremse: staticData.notbremse === true,

  zeitraumTage: config.tage,
  zeitraumVon: config.createdAtMin,
  zeitraumBis: config.createdAtMax || 'jetzt',
  seitenGeholt: stats.seiten,
  bestellungenGeprueft: stats.geprueft,
  ohneOffenenSaldo: stats.ohneOffenenSaldo,

  kandidaten: zeilen.length,
  summeOffen: summe(zeilen, 'offenerBetrag'),

  erstattetOk: erstattet.length,
  summeErstattet: summe(erstattet, 'refundBetrag'),
  pending: pending.length,
  summePending: summe(pending, 'refundBetrag'),
  trockenlaufWuerdeErstatten: trocken.length,
  summeTrockenlauf: summe(trocken, 'refundBetrag'),

  ueberMaxbetrag: nach('UEBER_MAXBETRAG').length,
  unterMindestbetrag: nach('UNTER_MINDESTBETRAG').length,
  saldoAusgeglichen: nach('KEIN_BEDARF').length,
  limitErreicht: nach('LIMIT_LAUF').length,
  fehler: zeilen.filter(z => ['GRAPHQL_FEHLER', 'USER_ERROR', 'KEIN_REFUND',
    'GATEWAY_FEHLER', 'KEINE_TRANSAKTION', 'NICHT_ERSTATTBAR'].includes(z.refundStatus)).length,

  manuellPruefen: pruefen.length,
  imFetchUebersprungen: skipped.length,

  budgetVerbraucht: Number(staticData.refundSumme || 0).toFixed(2),
  budgetGrenze: Number(config.maxSummeProLauf).toFixed(2)
};

// Zu Prüfende zuerst, dann nach offenem Betrag absteigend.
const sortiert = [...zeilen].sort((a, b) =>
  (b.manuellPruefen === true) - (a.manuellPruefen === true)
  || Number(b.offenerBetrag) - Number(a.offenerBetrag));

return [
  { json: zusammenfassung },
  ...sortiert.map(z => ({ json: { zeile: 'KANDIDAT', ...z } })),
  ...skipped.map(s => ({ json: { zeile: 'UEBERSPRUNGEN', ...s } }))
];

// Input dieses Nodes ist 'Token holen 2' (OAuth-Antwort), nicht die Bestellung.
// Die Bestelldaten deshalb direkt aus dem Loop holen.
const item = $('Loop Over Items').first().json;

// maximumRefundableV2 auf order.transactions liefert immer 0 – der Wert wird
// nur im Kontext von SuggestedRefund befuellt. Deshalb suggestedRefund abfragen.
const body = {
  query: `query($id: ID!) {
    order(id: $id) {
      id
      name
      totalOutstandingSet { presentmentMoney { amount currencyCode } }
      suggestedRefund {
        maximumRefundableSet { presentmentMoney { amount currencyCode } }
        suggestedTransactions {
          gateway
          kind
          amountSet { presentmentMoney { amount currencyCode } }
          maximumRefundableSet { presentmentMoney { amount currencyCode } }
          parentTransaction { id kind status }
        }
      }
      transactions(first: 20) {
        id
        kind
        status
        gateway
        amountSet { presentmentMoney { amount currencyCode } }
      }
    }
  }`,
  variables: { id: item.orderGid }
};

return {
  json: {
    ...item,
    accessToken: $('Token holen 2').first().json.access_token,
    gqlBody: JSON.stringify(body)
  }
};

const resp = $input.item.json;
const order = resp?.data?.order;
if (!order) {
  throw new Error('Order-Query ohne Ergebnis: ' + JSON.stringify(resp).slice(0, 500));
}

const config = $('Config').first().json.config;
const src = $('Loop Over Items').first().json;
const staticData = $getWorkflowStaticData('global');

// Der Saldo wird hier ERNEUT gelesen, nicht aus dem Fetch uebernommen.
// Zwischen Scan und Refund koennen Minuten liegen; in der Zeit kann jemand
// manuell erstattet haben. Sonst erstattet der Flow ein zweites Mal.
const outstanding = Number(order.totalOutstandingSet?.presentmentMoney?.amount || 0);
const currency = order.totalOutstandingSet?.presentmentMoney?.currencyCode || src.currency;

// Obergrenze + Parent aus suggestedRefund. maximumRefundableV2 auf
// order.transactions liefert immer 0 und ist als Deckel unbrauchbar.
const sr = order.suggestedRefund || null;
const sugg = (sr?.suggestedTransactions || [])[0] || null;

let maxRefund = Number(
  sugg?.maximumRefundableSet?.presentmentMoney?.amount
  ?? sr?.maximumRefundableSet?.presentmentMoney?.amount
  ?? 0
);
let parentId = sugg?.parentTransaction?.id || null;
let gateway = sugg?.gateway || null;

// Fallback ueber die Transaktionsliste, falls suggestedRefund leer bleibt
if (!parentId || !maxRefund) {
  const parent = (order.transactions || []).find(t =>
    ['SALE', 'CAPTURE'].includes(t.kind) && t.status === 'SUCCESS'
  );
  parentId = parentId || parent?.id || null;
  gateway = gateway || parent?.gateway || null;
  if (!maxRefund) {
    maxRefund = Number(parent?.amountSet?.presentmentMoney?.amount || 0);
  }
}

const gewuenscht = Math.abs(Math.min(outstanding, 0));
const bisher = Number(staticData.refundSumme || 0);

let refundNoetig = false;
let betrag = 0;
let gedeckelt = false;
let status = null;
let grund = null;
let manuellPruefen = false;

if (src.notbremse) {
  status = 'NOTBREMSE';
  grund = 'Mehr als ' + config.maxKandidatenProLauf + ' Kandidaten im Lauf – '
    + 'kein automatischer Refund, bitte Ursache prüfen';
  manuellPruefen = true;
} else if (outstanding >= 0) {
  status = 'KEIN_BEDARF';
  grund = 'Saldo inzwischen ausgeglichen (outstanding ' + outstanding + ') – ggf. bereits erstattet';
} else if (gewuenscht < config.mindestBetrag) {
  status = 'UNTER_MINDESTBETRAG';
  grund = 'Betrag ' + gewuenscht.toFixed(2) + ' unter Config.mindestBetrag';
} else if (gewuenscht > config.maxBetrag) {
  status = 'UEBER_MAXBETRAG';
  grund = 'Betrag ' + gewuenscht.toFixed(2) + ' über Config.maxBetrag ('
    + config.maxBetrag + ') – manuell erstatten';
  manuellPruefen = true;
} else if (bisher + gewuenscht > config.maxSummeProLauf) {
  status = 'LIMIT_LAUF';
  grund = 'Lauf-Limit erreicht: bereits ' + bisher.toFixed(2) + ' von max. '
    + config.maxSummeProLauf + ' erstattet – Rest manuell oder nächster Lauf';
  manuellPruefen = true;
} else if (!parentId || !gateway) {
  status = 'KEINE_TRANSAKTION';
  grund = 'Keine erstattbare Zahlungstransaktion gefunden – manuell erstatten';
  manuellPruefen = true;
} else {
  betrag = Math.round(Math.min(gewuenscht, maxRefund) * 100) / 100;
  gedeckelt = betrag < gewuenscht;

  if (betrag <= 0) {
    status = 'NICHT_ERSTATTBAR';
    grund = 'Erstattbarer Betrag ist 0 (maxRefund ' + maxRefund + ') – manuell erstatten';
    manuellPruefen = true;
  } else if (config.trockenlauf) {
    status = 'TROCKENLAUF';
    grund = 'Trockenlauf aktiv – würde ' + betrag.toFixed(2) + ' ' + currency + ' erstatten';
  } else {
    refundNoetig = true;
    // Budget sofort reservieren, nicht erst nach dem Erfolg: ein haengender
    // Refund darf das Lauf-Limit nicht umgehen.
    staticData.refundSumme = bisher + betrag;
    if (gedeckelt) {
      grund = 'Teilerstattung: ' + betrag.toFixed(2) + ' von ' + gewuenscht.toFixed(2)
        + ' (Limit ' + maxRefund + ')';
    }
  }
}

return {
  json: {
    orderId: src.orderId,
    orderGid: order.id,
    orderName: order.name,
    land: src.land,
    adminUrl: src.adminUrl,
    currency,
    outstanding,
    maxRefund,
    refundNoetig,
    refundBetrag: betrag.toFixed(2),
    gedeckelt,
    parentTransactionId: parentId,
    gateway,
    status,
    grund,
    manuellPruefen,
    accessToken: $('Token holen 2').first().json.access_token
  }
};

const item = $input.item.json;
const config = $('Config').first().json.config;

// WICHTIG: keine refundLineItems. Reine Geldrueckgabe, keine Retoure, keine
// Bestandsbuchung. Bei Bestellungen, deren Position per Order Edit auf 0
// gesetzt wurde, lehnt Shopify ein RefundLineItem darauf ohnehin ab.
// Refund.transactions ist eine Connection -> edges { node { ... } }.
const body = {
  query: `mutation refundCreate($input: RefundInput!) {
    refundCreate(input: $input) {
      refund {
        id
        createdAt
        totalRefundedSet { presentmentMoney { amount currencyCode } }
        transactions(first: 5) {
          edges {
            node { id kind status gateway errorCode }
          }
        }
      }
      userErrors { field message }
    }
  }`,
  variables: {
    input: {
      orderId: item.orderGid,
      currency: item.currency,
      notify: config.notifyCustomer,
      note: config.note,
      transactions: [{
        orderId: item.orderGid,
        parentId: item.parentTransactionId,
        gateway: item.gateway,
        kind: 'REFUND',
        amount: item.refundBetrag
      }]
    }
  }
};

return {
  json: {
    ...item,
    gqlBody: JSON.stringify(body)
  }
};

const resp = $input.item.json;
const src = $('Query bauen (refundCreate)').first().json;

// GraphQL-Fehler auf oberster Ebene (ungueltige Query, fehlender Scope, ...).
// Shopify antwortet dabei mit HTTP 200, der HTTP-Node schlaegt also nicht fehl.
const gqlErrors = resp?.errors || [];

const payload = resp?.data?.refundCreate;
const errs = payload?.userErrors || [];
const refund = payload?.refund || null;

// Refund.transactions ist eine Connection
const txs = (refund?.transactions?.edges || []).map(e => e.node);

// Ein Refund-Objekt allein heisst nicht, dass Geld geflossen ist ->
// Status der Refund-Transaktionen auswerten.
const problem = txs.filter(t => ['FAILURE', 'ERROR'].includes(t.status));

let status = 'OK';
if (gqlErrors.length) status = 'GRAPHQL_FEHLER';
else if (errs.length) status = 'USER_ERROR';
else if (!refund) status = 'KEIN_REFUND';
else if (problem.length) status = 'GATEWAY_FEHLER';
else if (txs.some(t => t.status === 'PENDING')) status = 'PENDING';

const erstattet = status === 'OK' || status === 'PENDING';

const ergebnis = {
  status,
  orderId: src.orderId,
  orderName: src.orderName,
  land: src.land,
  adminUrl: src.adminUrl,
  currency: src.currency,
  refundBetrag: src.refundBetrag,
  gedeckelt: src.gedeckelt,
  gateway: src.gateway,
  refundId: refund?.id || null,
  tatsaechlichErstattet: refund?.totalRefundedSet?.presentmentMoney?.amount || null,
  transaktionen: txs,
  userErrors: errs,
  gqlErrors: gqlErrors.map(e => e.message),
  grund: src.grund,
  manuellPruefen: status !== 'OK'
};

const staticData = $getWorkflowStaticData('global');
if (!staticData.ergebnisse) staticData.ergebnisse = {};
staticData.ergebnisse[src.orderId] = ergebnis;

// Ist der Refund nicht durchgegangen, das reservierte Budget zurueckgeben,
// sonst blockiert ein Fehlschlag das Lauf-Limit fuer die naechsten Faelle.
if (!erstattet) {
  staticData.refundSumme = Math.max(
    0,
    Number(staticData.refundSumme || 0) - Number(src.refundBetrag || 0)
  );
}

// Bewusst kein throw: ein abgelehnter Refund soll den Loop nicht stoppen.
return { json: ergebnis };

const item = $input.item.json;
const config = $('Config').first().json.config;

// orderGid und Token liegen nicht im Ergebnis-Item -> aus den Vorgaenger-Nodes holen
const orderGid = $('Query bauen (refundCreate)').first().json.orderGid;

const body = {
  query: `mutation tagsAdd($id: ID!, $tags: [String!]!) {
    tagsAdd(id: $id, tags: $tags) {
      node { id }
      userErrors { field message }
    }
  }`,
  variables: {
    id: orderGid,
    tags: [config.tag]
  }
};

return {
  json: {
    ...item,
    orderGid,
    tag: config.tag,
    accessToken: $('Token holen 2').first().json.access_token,
    gqlBody: JSON.stringify(body)
  }
};

const resp = $input.item.json;
const src = $('Query bauen (Tag)').first().json;

const gqlErrors = resp?.errors || [];
const errs = resp?.data?.tagsAdd?.userErrors || [];
const ok = !gqlErrors.length && !errs.length && !!resp?.data?.tagsAdd?.node?.id;

const tagInfo = {
  tag: src.tag,
  tagGesetzt: ok,
  tagFehler: [...gqlErrors.map(e => e.message), ...errs.map(e => e.message)]
};

// Ergebnis-Eintrag dieser Bestellung nachtraeglich ergaenzen. Ein fehlendes Tag
// ist kein Geldproblem, aber es macht den Lauf im Admin unauffindbar.
const staticData = $getWorkflowStaticData('global');
const eintrag = staticData.ergebnisse?.[src.orderId];
if (eintrag) {
  Object.assign(eintrag, tagInfo);
  if (!ok) eintrag.manuellPruefen = true;
}

// Bewusst kein throw: ein fehlgeschlagenes Tag soll den Loop nicht stoppen.
return { json: { ...src, gqlBody: undefined, accessToken: undefined, ...tagInfo } };

const item = $input.item.json;

// Status und manuellPruefen kommen bereits fertig aus 'Refund-Betrag ermitteln'.
const ergebnis = {
  status: item.status,
  orderId: item.orderId,
  orderName: item.orderName,
  land: item.land,
  adminUrl: item.adminUrl,
  currency: item.currency,
  outstanding: item.outstanding,
  refundBetrag: item.status === 'TROCKENLAUF' ? item.refundBetrag : '0.00',
  maxRefund: item.maxRefund,
  gateway: item.gateway,
  refundId: null,
  grund: item.grund,
  manuellPruefen: item.manuellPruefen === true
};

const staticData = $getWorkflowStaticData('global');
if (!staticData.ergebnisse) staticData.ergebnisse = {};
staticData.ergebnisse[item.orderId] = ergebnis;

return { json: ergebnis };

// Fasst alle Report-Zeilen zu EINER Mail zusammen.
// Ohne diesen Node wuerde 'Send email' pro Report-Zeile eine Mail schicken.

// true = an ruhigen Tagen gar keine Mail (Node gibt dann 0 Items zurueck)
const NUR_BEI_TREFFERN = false;

const items = $input.all().map(i => i.json);
const zus = items.find(i => i.zeile === 'ZUSAMMENFASSUNG') || {};
const kandidaten = items.filter(i => i.zeile === 'KANDIDAT');
const uebersprungen = items.filter(i => i.zeile === 'UEBERSPRUNGEN');

if (NUR_BEI_TREFFERN && kandidaten.length === 0) return [];

const esc = (v) => String(v ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const datum = (iso) => {
  if (!iso) return '';
  const d = new Date(iso);
  return isNaN(d) ? String(iso) : d.toLocaleDateString('de-DE');
};

const farbe = {
  OK: '#1a7f37',
  PENDING: '#b35900',
  TROCKENLAUF: '#6b7280',
  KEIN_BEDARF: '#6b7280',
  UNTER_MINDESTBETRAG: '#6b7280'
};

const th = 'style="text-align:left;padding:6px 10px;border-bottom:2px solid #ddd;font-size:13px"';
const td = 'style="padding:6px 10px;border-bottom:1px solid #eee;font-size:13px"';
const tdR = 'style="padding:6px 10px;border-bottom:1px solid #eee;font-size:13px;text-align:right;white-space:nowrap"';

const zeilen = kandidaten.map(k => `
  <tr${k.manuellPruefen ? ' style="background:#fff8f0"' : ''}>
    <td ${td}><a href="${esc(k.adminUrl)}">${esc(k.orderName)}</a></td>
    <td ${td}>${esc(datum(k.createdAt))}</td>
    <td ${td}>${esc(k.land)}</td>
    <td ${tdR}>${esc(k.offenerBetrag)} ${esc(k.currency)}</td>
    <td ${tdR}><strong>${esc(k.refundBetrag)}</strong></td>
    <td ${td}><span style="color:${farbe[k.refundStatus] || '#b00020'}">${esc(k.refundStatus)}</span></td>
    <td ${td}>${k.tagGesetzt ? '✓' : ''}</td>
    <td ${td}>${esc(k.grund)}</td>
  </tr>`).join('');

const tabelle = kandidaten.length ? `
<table cellspacing="0" cellpadding="0" style="border-collapse:collapse;width:100%;max-width:1000px">
  <tr>
    <th ${th}>Bestellung</th>
    <th ${th}>Datum</th>
    <th ${th}>Land</th>
    <th ${th} style="text-align:right">Offen</th>
    <th ${th} style="text-align:right">Erstattet</th>
    <th ${th}>Status</th>
    <th ${th}>Tag</th>
    <th ${th}>Hinweis</th>
  </tr>
  ${zeilen}
</table>` : '<p>Keine Bestellung mit offenem Guthaben im Zeitraum.</p>';

const skipBlock = uebersprungen.length ? `
<h3 style="font-size:14px;margin:24px 0 6px">Übersprungen (${uebersprungen.length})</h3>
<ul style="font-size:13px;margin:0;padding-left:18px">
  ${uebersprungen.map(s => `<li>${esc(s.orderName || s.orderId)}: ${esc(s.grund)}</li>`).join('')}
</ul>` : '';

// Auffaellige Laufzustaende gehoeren nach ganz oben, nicht in eine Tabellenzeile.
const warnungen = [];
if (zus.notbremse) {
  warnungen.push('NOTBREMSE: mehr als erlaubt viele Kandidaten – in diesem Lauf wurde '
    + 'nichts erstattet. Bitte Ursache prüfen.');
}
if (zus.modus && zus.modus !== 'SCHARF') warnungen.push(zus.modus);
if (Number(zus.limitErreicht) > 0) {
  warnungen.push('Lauf-Budget erschöpft: ' + zus.limitErreicht
    + ' Bestellung(en) wurden nicht erstattet.');
}

const warnBlock = warnungen.length ? `
<div style="border-left:4px solid #b00020;background:#fff4f4;padding:10px 14px;margin:0 0 18px;font-size:13px">
  ${warnungen.map(w => `<div>${esc(w)}</div>`).join('')}
</div>` : '';

const mailText = `
<div style="font-family:Arial,Helvetica,sans-serif;color:#222">
  <h2 style="font-size:18px;margin:0 0 4px">Shopify – offene Salden, letzte ${esc(zus.zeitraumTage)} Tage</h2>
  <p style="font-size:13px;color:#666;margin:0 0 16px">
    Zeitraum ${esc(datum(zus.zeitraumVon))} bis ${esc(zus.zeitraumBis === 'jetzt' ? 'heute' : datum(zus.zeitraumBis))}
    &middot; ${esc(zus.bestellungenGeprueft)} Bestellungen geprüft
  </p>

  ${warnBlock}

  <table cellspacing="0" cellpadding="0" style="border-collapse:collapse;margin:0 0 20px">
    <tr><td ${td}>Bestellungen mit offenem Guthaben</td><td ${tdR}><strong>${esc(zus.kandidaten)}</strong></td><td ${tdR}>${esc(zus.summeOffen)} EUR</td></tr>
    <tr><td ${td}>erstattet</td><td ${tdR}>${esc(zus.erstattetOk)}</td><td ${tdR}><strong>${esc(zus.summeErstattet)} EUR</strong></td></tr>
    <tr><td ${td}>in Abwicklung (pending)</td><td ${tdR}>${esc(zus.pending)}</td><td ${tdR}>${esc(zus.summePending)} EUR</td></tr>
    <tr><td ${td}>über Maxbetrag – manuell</td><td ${tdR}>${esc(zus.ueberMaxbetrag)}</td><td ${tdR}></td></tr>
    <tr><td ${td}>Saldo inzwischen ausgeglichen</td><td ${tdR}>${esc(zus.saldoAusgeglichen)}</td><td ${tdR}></td></tr>
    <tr><td ${td}>Fehler</td><td ${tdR}>${esc(zus.fehler)}</td><td ${tdR}></td></tr>
    <tr><td ${td}><strong>manuell prüfen</strong></td><td ${tdR}><strong>${esc(zus.manuellPruefen)}</strong></td><td ${tdR}></td></tr>
    <tr><td ${td}>Lauf-Budget</td><td ${tdR}>${esc(zus.budgetVerbraucht)}</td><td ${tdR}>von ${esc(zus.budgetGrenze)} EUR</td></tr>
  </table>

  ${tabelle}
  ${skipBlock}

  <p style="font-size:12px;color:#888;margin-top:24px">
    Workflow-ID ${$workflow.id}, Lauf ${esc(zus.lauf)}
  </p>
</div>`;

const titel = `Bücherbüchse | Offene Salden: ${esc(zus.erstattetOk)} erstattet (${esc(zus.summeErstattet)} EUR)`
  + (Number(zus.manuellPruefen) > 0 ? `, ${esc(zus.manuellPruefen)} zu prüfen` : '');

return [{ json: { titel, mailText, anzahlKandidaten: kandidaten.length } }];
